:host { display: block; }

.art {
    display: block;
    width: 100%;
    max-width: 340px;
    height: auto;
    font-family: inherit;
}

.art-wide {
    max-width: 760px;
}

/* illustration palette */
.frame { fill: #ffffff; stroke: #c9c9c9; stroke-width: 1.25; }
.box-org { fill: #eef4ff; stroke: #0176d3; stroke-width: 1.5; }
.box-git { fill: #f0f7ec; stroke: #2e844a; stroke-width: 1.5; }
.box-plain { fill: #ffffff; stroke: #747474; stroke-width: 1.25; }
.edge { fill: none; stroke: #747474; stroke-width: 1.5; }
.fill-edge { fill: #747474; }
.field { fill: #ffffff; stroke: #939393; }
.field-off { fill: #f3f3f3; stroke: #c9c9c9; }
.btn { fill: #ffffff; stroke: #0176d3; }
.btn-brand { fill: #0176d3; }
.seg { fill: #ffffff; stroke: #c9c9c9; }
.seg-on { fill: #0176d3; }
.ok { fill: #ebf7e6; stroke: #2e844a; }
.row-head { fill: #f3f3f3; }
.check { fill: #ffffff; stroke: #939393; }
.check-on { fill: #0176d3; }
.tick { fill: none; stroke: #ffffff; stroke-width: 1.75; }
.item { fill: #ffffff; stroke: #e5e5e5; }
.item-on { fill: #eef4ff; stroke: #0176d3; }
.code { fill: #fafaf9; stroke: #e5e5e5; }
.line-add { fill: #ebf7e6; }
.line-del { fill: #fef1ee; }
.pill-run { fill: #fef1cd; }
.pill-open { fill: #eef4ff; }
.pill-ok { fill: #ebf7e6; }
.pill-bad { fill: #fef1ee; }

.t-title { font-size: 14px; font-weight: 700; fill: #181818; }
.t-sub { font-size: 11px; fill: #5c5c5c; }
.t-body { font-size: 11.5px; fill: #181818; }
.t-label { font-size: 11px; font-weight: 700; fill: #444444; }
.t-note { font-size: 11px; fill: #5c5c5c; font-style: italic; }
.t-on { font-size: 11px; font-weight: 700; fill: #ffffff; }
.t-ok { font-size: 11px; fill: #194e31; }
.t-del { font-size: 11.5px; fill: #ba0517; }
.t-link { font-size: 11.5px; fill: #0b5cab; text-decoration: underline; }
.t-mono { font-family: monospace; font-size: 10.5px; fill: #444444; }
.t-mono-add { font-family: monospace; font-size: 10.5px; fill: #194e31; }
.t-mono-del { font-family: monospace; font-size: 10.5px; fill: #8e030f; }
.t-pill-run { font-size: 10px; fill: #8c4b02; }
.t-pill-open { font-size: 10px; fill: #0b5cab; }
.t-pill-ok { font-size: 10px; fill: #194e31; }
.t-pill-bad { font-size: 10px; fill: #8e030f; }

.lane-a { fill: #f7f9fc; }
.lane-b { fill: #ffffff; }
.seq-line { fill: none; stroke: #9faab8; stroke-width: 1.5; stroke-dasharray: 4 3; }
.seq-dot { fill: #0176d3; }
.seq-test { fill: #2e844a; }
.seq-opt { fill: #ffffff; stroke: #0176d3; stroke-width: 1.5; stroke-dasharray: 3 2; }
.t-seq { font-size: 11px; font-weight: 700; fill: #ffffff; }
.t-seq-opt { font-size: 11px; font-weight: 700; fill: #0176d3; }
.btn-git { fill: #2e844a; }
